import React, { useEffect, useState } from 'react';
import {
  AlertTriangle,
  FileText,
  History,
  MessageSquare,
  Pause,
  Play,
  Send,
  Sliders,
  Square,
  X,
} from 'lucide-react';
import { apiRequest } from '../api/client';
import { AGENT_WORKSTATIONS } from '../game/worldMap';
import { useSimulatorStore } from '../stores/useSimulatorStore';
import type { AgentItem, ConversationItem } from '../types/simulator';

interface Props {
  agent: AgentItem;
  onClose: () => void;
}

type DrawerTab = 'control' | 'chat' | 'history';

export const AgentDetailDrawer: React.FC<Props> = ({ agent, onClose }) => {
  const { refreshAll } = useSimulatorStore();
  const [subTab, setSubTab] = useState<DrawerTab>('control');

  const [conversations, setConversations] = useState<ConversationItem[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [sendingChat, setSendingChat] = useState(false);

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDesc, setNewTaskDesc] = useState('');
  const [assigning, setAssigning] = useState(false);
  const [reportText, setReportText] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);

  const spec = AGENT_WORKSTATIONS[agent.id];

  const loadConversations = async () => {
    try {
      const data = await apiRequest<ConversationItem[]>(`/api/agents/${agent.id}/conversations`);
      setConversations(data);
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    setReportText(null);
    setActionError(null);
    void loadConversations();
  }, [agent.id]);

  const activeConv = conversations[0] || null;
  const recentTasks = agent.recent_tasks || [];
  const latestTask = agent.current_task || recentTasks[0] || null;

  const handleAssignTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskTitle.trim() || !newTaskDesc.trim()) return;
    setAssigning(true);
    setActionError(null);
    try {
      await apiRequest(`/api/agents/${agent.id}/tasks`, {
        method: 'POST',
        body: JSON.stringify({
          title: newTaskTitle.trim(),
          description: newTaskDesc.trim(),
          priority: 4,
          auto_execute: true,
        }),
      });
      setNewTaskTitle('');
      setNewTaskDesc('');
      await refreshAll();
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Lỗi khi giao việc');
    } finally {
      setAssigning(false);
    }
  };

  const handleTaskAction = async (taskId: string, action: 'pause' | 'resume' | 'cancel') => {
    setActionError(null);
    try {
      const query = action === 'resume' ? '?sync=true' : '';
      await apiRequest(`/api/tasks/${taskId}/${action}${query}`, { method: 'POST' });
      await refreshAll();
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Lỗi điều khiển nhiệm vụ');
    }
  };

  const handleRequestReport = async () => {
    setActionError(null);
    try {
      const res = await apiRequest<{ report: string; model_id: string }>(`/api/agents/${agent.id}/report`, {
        method: 'POST',
      });
      setReportText(`[${res.model_id}] ${res.report}`);
      await loadConversations();
      await refreshAll();
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Không thể lấy báo cáo');
    }
  };

  const handleSendChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim()) return;
    setSendingChat(true);
    setActionError(null);
    try {
      await apiRequest(`/api/agents/${agent.id}/messages`, {
        method: 'POST',
        body: JSON.stringify({
          message: chatInput.trim(),
          conversation_id: activeConv?.id || null,
        }),
      });
      setChatInput('');
      await loadConversations();
      await refreshAll();
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Gửi tin nhắn thất bại');
    } finally {
      setSendingChat(false);
    }
  };

  return (
    <div className="flex h-full flex-col rounded-2xl border border-cyan-500/30 bg-slate-900/95 p-4 shadow-2xl">
      {/* Compact Specialist Header */}
      <div className="flex items-center justify-between pb-3">
        <div className="flex items-center gap-3">
          <div
            className="flex h-10 w-10 items-center justify-center rounded-xl border border-white/20 text-sm font-black text-slate-950 shadow-lg"
            style={{ backgroundColor: spec?.primaryColor || agent.avatar_color }}
          >
            {spec?.badgeSymbol || 'AI'}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-sm font-bold text-white">{agent.name}</h2>
              <span className="rounded-md bg-slate-800 px-2 py-0.5 text-[10px] font-bold text-cyan-300">
                {agent.status}
              </span>
            </div>
            <p className="text-[11px] text-slate-400">{spec?.vietnameseRole || agent.role}</p>
          </div>
        </div>
        <button
          type="button"
          onClick={onClose}
          className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-800 hover:text-white"
        >
          <X className="h-4 w-4" />
        </button>
      </div>

      {/* Clean 3-Tab Segmented Switcher */}
      <div className="grid grid-cols-3 gap-1 rounded-xl border border-slate-800 bg-slate-950 p-1 text-[11px] font-semibold">
        <button
          type="button"
          onClick={() => setSubTab('control')}
          className={`flex items-center justify-center gap-1 rounded-lg py-1.5 transition ${
            subTab === 'control' ? 'bg-cyan-500 text-slate-950' : 'text-slate-400 hover:text-white'
          }`}
        >
          <Sliders className="h-3.5 w-3.5" /> Điều hành
        </button>
        <button
          type="button"
          onClick={() => setSubTab('chat')}
          className={`flex items-center justify-center gap-1 rounded-lg py-1.5 transition ${
            subTab === 'chat' ? 'bg-cyan-500 text-slate-950' : 'text-slate-400 hover:text-white'
          }`}
        >
          <MessageSquare className="h-3.5 w-3.5" /> Hội thoại
        </button>
        <button
          type="button"
          onClick={() => setSubTab('history')}
          className={`flex items-center justify-center gap-1 rounded-lg py-1.5 transition ${
            subTab === 'history' ? 'bg-cyan-500 text-slate-950' : 'text-slate-400 hover:text-white'
          }`}
        >
          <History className="h-3.5 w-3.5" /> Lịch sử ({recentTasks.length})
        </button>
      </div>

      {actionError && (
        <div className="mt-2 rounded-lg border border-rose-500/40 bg-rose-500/10 p-2 text-xs text-rose-300">
          {actionError}
        </div>
      )}

      {/* TAB 1: CONTROL & ASSIGN TASK */}
      {subTab === 'control' && (
        <div className="mt-3 flex-1 space-y-3 overflow-y-auto pr-1 text-xs">
          {/* Instant Telemetry Pills */}
          <div className="grid grid-cols-3 gap-2">
            <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-2.5">
              <span className="text-[10px] text-slate-500">Model Đang Dùng</span>
              <p className="mt-0.5 truncate font-semibold text-cyan-300">
                {latestTask?.current_model_id || 'Auto Free-First'}
              </p>
            </div>
            <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-2.5">
              <span className="text-[10px] text-slate-500">Token Đã Dùng</span>
              <p className="mt-0.5 font-semibold text-emerald-300">
                {agent.tokens_consumed.toLocaleString()}
              </p>
            </div>
            <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-2.5">
              <span className="text-[10px] text-slate-500">Chi phí Thực</span>
              <p className="mt-0.5 font-semibold text-amber-300">
                ${agent.recorded_cost_usd.toFixed(4)}
              </p>
            </div>
          </div>

          {/* Current Task Progress & Controls */}
          <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-3 space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-[11px] font-bold uppercase text-slate-400">Tiến độ Công việc</span>
              <button
                type="button"
                onClick={handleRequestReport}
                className="flex items-center gap-1 rounded-lg border border-cyan-500/40 bg-cyan-500/10 px-2 py-1 text-[11px] font-semibold text-cyan-300 hover:bg-cyan-500/20"
              >
                <FileText className="h-3 w-3" /> Yêu cầu báo cáo
              </button>
            </div>

            {latestTask ? (
              <>
                <div className="flex items-center justify-between gap-2">
                  <span className="font-semibold text-white">{latestTask.title}</span>
                  <span className="rounded bg-slate-800 px-1.5 py-0.5 text-[10px] font-bold text-cyan-300">
                    {latestTask.status}
                  </span>
                </div>
                <div className="flex items-center justify-between text-[11px] text-slate-400">
                  <span>
                    Checkpoint: {latestTask.completed_steps}/{latestTask.total_steps} bước
                  </span>
                  <span className="font-bold text-emerald-300">{latestTask.progress_pct}%</span>
                </div>
                <div className="h-2 w-full overflow-hidden rounded-full bg-slate-800">
                  <div
                    className="h-full bg-gradient-to-r from-cyan-400 to-emerald-400 transition-all"
                    style={{ width: `${latestTask.progress_pct}%` }}
                  />
                </div>
                {latestTask.result_summary && (
                  <p className="rounded-lg border border-slate-800 bg-slate-900 p-2 text-[11px] text-slate-300 line-clamp-3">
                    {latestTask.result_summary}
                  </p>
                )}
                <div className="flex flex-wrap gap-1.5 pt-1">
                  <button
                    type="button"
                    onClick={() => handleTaskAction(latestTask.id, 'pause')}
                    className="flex items-center gap-1 rounded-lg bg-amber-500/20 px-2.5 py-1 text-[11px] font-semibold text-amber-300 hover:bg-amber-500/30"
                  >
                    <Pause className="h-3 w-3" /> Tạm dừng
                  </button>
                  <button
                    type="button"
                    onClick={() => handleTaskAction(latestTask.id, 'resume')}
                    className="flex items-center gap-1 rounded-lg bg-emerald-500/20 px-2.5 py-1 text-[11px] font-semibold text-emerald-300 hover:bg-emerald-500/30"
                  >
                    <Play className="h-3 w-3" /> Tiếp tục
                  </button>
                  <button
                    type="button"
                    onClick={() => handleTaskAction(latestTask.id, 'cancel')}
                    className="flex items-center gap-1 rounded-lg bg-rose-500/20 px-2.5 py-1 text-[11px] font-semibold text-rose-300 hover:bg-rose-500/30"
                  >
                    <Square className="h-3 w-3" /> Hủy
                  </button>
                </div>
              </>
            ) : (
              <p className="text-[11px] text-slate-500">Agent đang sẵn sàng nhận lệnh mới.</p>
            )}

            {reportText && (
              <div className="rounded-lg border border-cyan-500/30 bg-cyan-950/30 p-2 text-[11px] text-cyan-200">
                {reportText}
              </div>
            )}
          </div>

          {/* Streamlined Assign Task Form */}
          <form
            onSubmit={handleAssignTask}
            className="rounded-xl border border-slate-800 bg-slate-950/80 p-3 space-y-2"
          >
            <span className="text-[11px] font-bold uppercase text-emerald-400">
              + Giao Nhiệm Vụ Mới
            </span>
            <input
              type="text"
              placeholder="Tên nhiệm vụ cần thực thi..."
              value={newTaskTitle}
              onChange={(e) => setNewTaskTitle(e.target.value)}
              className="w-full rounded-lg border border-slate-700 bg-slate-900 px-2.5 py-1.5 text-xs text-white"
            />
            <textarea
              rows={2}
              placeholder="Mô tả mục tiêu & yêu cầu đầu ra..."
              value={newTaskDesc}
              onChange={(e) => setNewTaskDesc(e.target.value)}
              className="w-full rounded-lg border border-slate-700 bg-slate-900 px-2.5 py-1.5 text-xs text-white"
            />
            <button
              type="submit"
              disabled={assigning}
              className="w-full rounded-lg bg-emerald-500 py-2 text-xs font-bold text-slate-950 hover:bg-emerald-400 disabled:opacity-50"
            >
              {assigning ? 'Đang gửi lệnh...' : 'Giao Việc Ngay'}
            </button>
          </form>
        </div>
      )}

      {/* TAB 2: FULL-HEIGHT LIVE CHAT */}
      {subTab === 'chat' && (
        <div className="mt-3 flex flex-1 flex-col overflow-hidden rounded-xl border border-slate-800 bg-slate-950/80 p-3">
          <div className="flex-1 space-y-2 overflow-y-auto pr-1">
            {!activeConv || activeConv.messages.length === 0 ? (
              <div className="py-12 text-center text-xs text-slate-500">
                Bắt đầu hội thoại trực tiếp với <strong className="text-slate-300">{agent.name}</strong>.
                <br />
                Mọi tin nhắn được lưu bền vững vào cơ sở dữ liệu.
              </div>
            ) : (
              activeConv.messages.map((m) => (
                <div
                  key={m.id}
                  className={`rounded-xl p-2.5 text-xs ${
                    m.sender_type === 'USER'
                      ? 'ml-6 bg-cyan-500/20 text-cyan-100 border border-cyan-500/30'
                      : 'mr-4 bg-slate-900 text-slate-200 border border-slate-800'
                  }`}
                >
                  <div className="flex items-center justify-between text-[10px] text-slate-400">
                    <span className="font-semibold">
                      {m.sender_type === 'USER' ? 'Admin' : agent.name}
                    </span>
                    {m.model_id && <span>{m.model_id}</span>}
                  </div>
                  <p className="mt-1 whitespace-pre-wrap leading-relaxed">{m.content}</p>
                </div>
              ))
            )}
          </div>
          <form onSubmit={handleSendChat} className="mt-2 flex gap-1.5 pt-2 border-t border-slate-800">
            <input
              type="text"
              placeholder={`Trao đổi với ${agent.name}...`}
              value={chatInput}
              onChange={(e) => setChatInput(e.target.value)}
              className="flex-1 rounded-lg border border-slate-700 bg-slate-900 px-3 py-2 text-xs text-white"
            />
            <button
              type="submit"
              disabled={sendingChat}
              className="flex items-center gap-1 rounded-lg bg-cyan-500 px-3.5 py-2 text-xs font-bold text-slate-950 hover:bg-cyan-400 disabled:opacity-50"
            >
              <Send className="h-3.5 w-3.5" />
            </button>
          </form>
        </div>
      )}

      {/* TAB 3: TASK HISTORY & ERROR LOGS */}
      {subTab === 'history' && (
        <div className="mt-3 flex-1 space-y-2 overflow-y-auto pr-1 text-xs">
          {recentTasks.length === 0 ? (
            <p className="py-10 text-center text-slate-500">Chưa có lịch sử nhiệm vụ.</p>
          ) : (
            recentTasks.map((t) => (
              <div key={t.id} className="rounded-xl border border-slate-800 bg-slate-950 p-3 space-y-1">
                <div className="flex items-center justify-between">
                  <span className="font-semibold text-white">{t.title}</span>
                  <span className="rounded bg-slate-800 px-1.5 py-0.5 text-[10px] text-cyan-300">
                    {t.status}
                  </span>
                </div>
                <p className="text-[11px] text-slate-400">
                  Tiến độ: {t.completed_steps}/{t.total_steps} ({t.progress_pct}%) • Model:{' '}
                  {t.current_model_id || '—'}
                </p>
                {t.error_log && t.error_log.length > 0 && (
                  <p className="text-[11px] text-rose-400">
                    <AlertTriangle className="mr-1 inline h-3 w-3" />
                    {t.error_log[t.error_log.length - 1].reason}
                  </p>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};
