  const [crawlingNews, setCrawlingNews] = useState<boolean>(false);
  const [previewItem, setPreviewItem] = useState<PendingNewsItem | null>(null);
  const [actionSuccessMsg, setActionSuccessMsg] = useState<string | null>(null);

  const loadMarketingReport = async () => {
    try {
      const res = await apiRequest<MarketingChannelsReport>('/api/business/marketing/channels');
      setMarketingReport(res);
    } catch {
      // ignore
    }
  };

  const loadPendingNews = async () => {
    try {
      const res = await apiRequest<PendingNewsItem[]>('/api/business/news/pending');
      setPendingNews(res || []);
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    loadMarketingReport();
    loadPendingNews();

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setPreviewItem(null);
        setSelectedTaskCheckpoints(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const handleApproveNews = async (approvalId: string) => {
    try {
      const res = await apiRequest<{ status: string; published_to_live_cdn: boolean; title: string }>(
        `/api/business/news/${approvalId}/approve`,
        { method: 'POST' }
      );
      setActionSuccessMsg(`✅ Đã phê duyệt và xuất bản bài báo "${res.title}" trực tiếp lên website 24/7!`);
      setTimeout(() => setActionSuccessMsg(null), 6000);
      setPreviewItem(null);
      await loadPendingNews();
      await refreshAll();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Lỗi khi phê duyệt bài viết');
    }
  };

  const handleRejectNews = async (approvalId: string) => {
    try {
      await apiRequest(`/api/business/news/${approvalId}/reject`, { method: 'POST' });
      setActionSuccessMsg('Đã từ chối bài viết.');
      setTimeout(() => setActionSuccessMsg(null), 3000);
      setPreviewItem(null);
      await loadPendingNews();
      await refreshAll();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Lỗi khi từ chối bài viết');
    }
  };

