import { create } from 'zustand';
import { apiRequest, getSessionToken, setSessionToken } from '../api/client';
import type {
  AgentItem,
  ApprovalItem,
  BusinessAnalytics,
  CostAnalytics,
  CredentialItem,
  MemoryArchiveData,
  NotificationItem,
  ProviderItem,
  RouterPolicy,
  SystemEvent,
  SystemStatus,
  TaskItem,
  UsageAnalytics,
  User,
} from '../types/simulator';

export type ScreenTab = 'world' | 'api-control' | 'operations';

interface SimulatorState {
  activeTab: ScreenTab;
  selectedRoomId: string;
  selectedAgentId: string | null;
  wsConnected: boolean;
  lastEventSeq: number;
  switchedAgentFlash: Record<string, number>;

  user: User | null;
  authError: string | null;
  globalBanner: string | null;

  systemStatus: SystemStatus | null;
  agents: AgentItem[];
  tasks: TaskItem[];
  providers: ProviderItem[];
  credentials: CredentialItem[];
  policy: RouterPolicy | null;
  notifications: NotificationItem[];
  events: SystemEvent[];
  usageAnalytics: UsageAnalytics | null;
  costAnalytics: CostAnalytics | null;
  businessAnalytics: BusinessAnalytics | null;
  memoryArchive: MemoryArchiveData | null;
  approvals: ApprovalItem[];
  googleOAuthNotice: string;

  setActiveTab: (tab: ScreenTab) => void;
  setSelectedRoomId: (roomId: string) => void;
  setSelectedAgentId: (agentId: string | null) => void;
  setWsConnected: (connected: boolean) => void;
  setGlobalBanner: (msg: string | null) => void;

  login: (email: string, password: string) => Promise<boolean>;
  logout: () => void;
  bootstrapSession: () => Promise<void>;
  refreshAll: () => Promise<void>;
  refreshCredentials: () => Promise<void>;
  handleRealtimeEvent: (raw: Record<string, unknown>) => void;
}

let refreshDebounceTimer: ReturnType<typeof setTimeout> | null = null;
let isRefreshingAll = false;

export const useSimulatorStore = create<SimulatorState>((set, get) => ({
  activeTab: 'world',
  selectedRoomId: 'command-center',
  selectedAgentId: null,
  wsConnected: false,
  lastEventSeq: 0,
  switchedAgentFlash: {},

  user: null,
  authError: null,
  globalBanner: null,

  systemStatus: null,
  agents: [],
  tasks: [],
  providers: [],
  credentials: [],
  policy: null,
  notifications: [],
  events: [],
  usageAnalytics: null,
  costAnalytics: null,
  businessAnalytics: null,
  memoryArchive: null,
  approvals: [],
  googleOAuthNotice: '',

  setActiveTab: (tab) => set({ activeTab: tab }),
  setSelectedRoomId: (roomId) => set({ selectedRoomId: roomId }),
  setSelectedAgentId: (agentId) => set({ selectedAgentId: agentId }),
  setWsConnected: (connected) => set({ wsConnected: connected }),
  setGlobalBanner: (msg) => set({ globalBanner: msg }),

  login: async (email, password) => {
    try {
      const res = await apiRequest<{ access_token: string; user: User }>('/api/auth/login', {
        method: 'POST',
        body: JSON.stringify({ email, password }),
      });
      setSessionToken(res.access_token);
      set({ user: res.user, authError: null });
      await get().refreshAll();
      if (res.user.role === 'admin') {
        await get().refreshCredentials();
      }
      return true;
    } catch (err) {
      set({ authError: err instanceof Error ? err.message : 'Đăng nhập thất bại' });
      return false;
    }
  },

  logout: () => {
    setSessionToken(null);
    set({ user: null, credentials: [] });
  },

  bootstrapSession: async () => {
    const existing = getSessionToken();
    if (existing) {
      try {
        const me = await apiRequest<User>('/api/auth/me');
        set({ user: me });
      } catch {
        setSessionToken(null);
      }
    }
    // In local dev, auto sign-in as primary owner account danhnpcd@gmail.com
    if (!get().user) {
      const ok = await get().login('danhnpcd@gmail.com', 'Admin@123456!');
      if (!ok) {
        await get().login('admin@simulator.local', 'Admin@123456!');
      }
      return;
    }
    await get().refreshAll();
    if (get().user?.role === 'admin') {
      await get().refreshCredentials();
    }
  },

  refreshCredentials: async () => {
    if (get().user?.role !== 'admin') {
      set({ credentials: [] });
      return;
    }
    try {
      const creds = await apiRequest<CredentialItem[]>('/api/credentials');
      set({ credentials: creds });
    } catch {
      // ignore if viewer/operator
    }
  },

  refreshAll: async () => {
    if (isRefreshingAll) return;
    isRefreshingAll = true;
    try {
      const [
        systemStatus,
        agents,
        tasks,
        providers,
        policy,
        notifications,
        events,
        usageAnalytics,
        costAnalytics,
        businessAnalytics,
        memoryArchive,
        approvals,
        googleCfg,
      ] = await Promise.all([
        apiRequest<SystemStatus>('/api/system/status'),
        apiRequest<AgentItem[]>('/api/agents'),
        apiRequest<TaskItem[]>('/api/tasks'),
        apiRequest<ProviderItem[]>('/api/providers'),
        apiRequest<RouterPolicy>('/api/router/policy'),
        apiRequest<NotificationItem[]>('/api/notifications'),
        apiRequest<SystemEvent[]>('/api/events?since_seq=0&limit=80'),
        apiRequest<UsageAnalytics>('/api/analytics/usage'),
        apiRequest<CostAnalytics>('/api/analytics/costs'),
        apiRequest<BusinessAnalytics>('/api/analytics/business'),
        apiRequest<MemoryArchiveData>('/api/memory/archive'),
        apiRequest<ApprovalItem[]>('/api/approvals'),
        apiRequest<{ separation_notice: string }>('/api/auth/google/config'),
      ]);

      const maxSeq = events.reduce((acc, e) => Math.max(acc, e.seq || 0), get().lastEventSeq);
      set({
        systemStatus,
        agents,
        tasks,
        providers,
        policy,
        notifications,
        events: [...events].reverse(),
        lastEventSeq: maxSeq,
        usageAnalytics,
        costAnalytics,
        businessAnalytics,
        memoryArchive,
        approvals,
        googleOAuthNotice: googleCfg.separation_notice,
        globalBanner: null, // Clear error banner on successful refresh!
      });
    } catch (err) {
      const errMsg = err instanceof Error ? err.message : 'Mất kết nối tới Backend API';
      if (errMsg.includes('429')) {
        // Silently retry in 2.5s without flashing alarming error banner
        setTimeout(() => void get().refreshAll(), 2500);
      } else {
        set({
          globalBanner: `Không thể kết nối Backend API: ${errMsg}`,
        });
      }
    } finally {
      isRefreshingAll = false;
    }
  },

  handleRealtimeEvent: (raw) => {
    const ev = raw as unknown as SystemEvent;
    const seq = typeof ev.seq === 'number' ? ev.seq : get().lastEventSeq;
    set((state) => {
      const exists = state.events.some((x) => x.event_id === ev.event_id);
      const nextEvents = exists ? state.events : [ev, ...state.events].slice(0, 100);
      const nextFlash = { ...state.switchedAgentFlash };
      if (ev.event_type === 'PROVIDER_SWITCHED' && ev.agent_id) {
        nextFlash[ev.agent_id] = Date.now() + 8000;
      }
      return {
        events: nextEvents,
        lastEventSeq: Math.max(state.lastEventSeq, seq),
        switchedAgentFlash: nextFlash,
      };
    });
    // Debounce state refresh to prevent concurrent API request storms
    if (refreshDebounceTimer) clearTimeout(refreshDebounceTimer);
    refreshDebounceTimer = setTimeout(() => {
      void get().refreshAll();
    }, 600);
  },
}));
