/**
 * Computes backend-truthful target coordinates for an AI character.
 * STRICT INTEGRITY RULE: Never animate an agent patrolling/working when status !== 'WORKING'.
 */
export function computeAgentWaypointTarget(
  status: string,
  agentId: string,
  spec: AgentVisualSpec,
  timeMs: number,
): { gx: number; gy: number; waypointIndex: number; stationDwelling: boolean } {
  const waypoints =
    spec.patrolWaypoints && spec.patrolWaypoints.length > 0
      ? spec.patrolWaypoints
      : ([[spec.gx, spec.gy]] as Array<[number, number]>);

  if (status !== 'WORKING') {
    return { gx: spec.gx, gy: spec.gy, waypointIndex: 0, stationDwelling: false };
  }

  // Each waypoint cycle is 3400ms (1900ms walking + 1500ms operating terminal)
  const seedOffset = agentId.split('').reduce((acc, ch) => acc + ch.charCodeAt(0), 0) * 410;
  const cycleMs = 3400;
  const elapsed = Math.max(0, timeMs + seedOffset);
  const slot = Math.floor(elapsed / cycleMs);
  const withinSlot = elapsed % cycleMs;

  const fromIdx = slot % waypoints.length;
  const toIdx = (slot + 1) % waypoints.length;
  const [fx, fy] = waypoints[fromIdx];
  const [tx, ty] = waypoints[toIdx];

  if (withinSlot < 1900) {
    const rawT = withinSlot / 1900;
    // Smooth ease-in-out cubic interpolation between workstations
    const smoothT = rawT < 0.5 ? 4 * rawT * rawT * rawT : 1 - Math.pow(-2 * rawT + 2, 3) / 2;
    return {
      gx: fx + (tx - fx) * smoothT,
      gy: fy + (ty - fy) * smoothT,
      waypointIndex: toIdx,
      stationDwelling: false,
    };
  }

  // Dwelling at target station: subtle console operation micro-shift
  const micro = Math.sin(timeMs / 240) * 0.05;
  return {
    gx: tx + micro,
    gy: ty - micro,
    waypointIndex: toIdx,
    stationDwelling: true,
  };
}

