export function gridToIso(gx: number, gy: number): { x: number; y: number } {
  return {
    x: (gx - gy) * (TILE_WIDTH / 2),
    y: (gx + gy) * (TILE_HEIGHT / 2),
  };
}

export function isoToGrid(isoX: number, isoY: number): { gx: number; gy: number } {
  const halfW = TILE_WIDTH / 2;
  const halfH = TILE_HEIGHT / 2;
  return {
    gx: (isoY / halfH + isoX / halfW) / 2,
    gy: (isoY / halfH - isoX / halfW) / 2,
  };
}
